-- 0021_generated_document_provenance.sql
-- A document the system authored is not a document the system received.
--
-- Malware scanning exists because uploads are untrusted input. A lease
-- agreement rendered by PropertyOS from its own template and its own records is
-- not input at all, and recording it as 'clean' would claim a scan that never
-- ran — exactly the kind of untrue status this schema avoids elsewhere.
--
-- So generated bytes get their own status. It is not quarantined, because there
-- is nothing to quarantine from, and it reads honestly in the document list.
alter type app.scan_status add value if not exists 'system_generated';
